using Microsoft.Data.Sqlite;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Google.Apis.Auth;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddCors(o => o.AddDefaultPolicy(p => p.AllowAnyHeader().AllowAnyMethod().AllowAnyOrigin()));
var app = builder.Build(); app.UseCors(); app.UseDefaultFiles(); app.UseStaticFiles();
var dbPath = Environment.GetEnvironmentVariable("NEBULA_DB_PATH") ?? Path.Combine(AppContext.BaseDirectory, "nebula.db");
string Conn() => new SqliteConnectionStringBuilder { DataSource = dbPath }.ToString();
await using (var c = new SqliteConnection(Conn())) { await c.OpenAsync(); var cmd = c.CreateCommand(); cmd.CommandText = @"
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, email TEXT UNIQUE NOT NULL, google_sub TEXT, password_hash TEXT, password_salt TEXT, role TEXT NOT NULL DEFAULT 'user', plan TEXT NOT NULL DEFAULT 'Free', plan_expires TEXT, created_utc TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL, expires_utc TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS promos(code TEXT PRIMARY KEY, duration_days INTEGER NOT NULL, max_uses INTEGER NOT NULL, uses INTEGER NOT NULL DEFAULT 0, expires_utc TEXT NOT NULL, created_by INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profiles(user_id INTEGER PRIMARY KEY, prefix TEXT NOT NULL DEFAULT '', avatar TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS chat_messages(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, content TEXT NOT NULL, message_type TEXT NOT NULL DEFAULT 'text', created_utc TEXT NOT NULL);
INSERT OR IGNORE INTO settings(key,value) VALUES('latestVersion','1.2.0'),('minimumVersion','1.2.0'),('downloadUrl','https://example.com/nebula-clean'),('updateMessage','Установите актуальную версию NEBULA CLEAN.');"; await cmd.ExecuteNonQueryAsync();
    // Upgrade databases created by earlier NEBULA CLEAN versions.
    var columns = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    var info = c.CreateCommand(); info.CommandText = "PRAGMA table_info(chat_messages)";
    await using (var reader = await info.ExecuteReaderAsync()) { while (await reader.ReadAsync()) columns.Add(reader.GetString(1)); }
    if (!columns.Contains("message_type")) { var migrate = c.CreateCommand(); migrate.CommandText = "ALTER TABLE chat_messages ADD COLUMN message_type TEXT NOT NULL DEFAULT 'text'"; await migrate.ExecuteNonQueryAsync(); }
}
string? adminEmail = Environment.GetEnvironmentVariable("NEBULA_ADMIN_EMAIL"); string? adminPassword = Environment.GetEnvironmentVariable("NEBULA_ADMIN_PASSWORD");
if (!string.IsNullOrWhiteSpace(adminEmail) && !string.IsNullOrWhiteSpace(adminPassword)) await EnsureAdmin(adminEmail, adminPassword);

app.MapGet("/health", () => Results.Ok(new { status = "ok", service = "NEBULA API" }));

app.MapGet("/api/profile", async (HttpRequest req) => {
 var u=await GetUser(req); if(u is null)return Results.Unauthorized();
 await using var c=new SqliteConnection(Conn()); await c.OpenAsync(); var q=c.CreateCommand(); q.CommandText="SELECT prefix,avatar FROM profiles WHERE user_id=$id"; q.Parameters.AddWithValue("$id",u.Id); await using var r=await q.ExecuteReaderAsync();
 return await r.ReadAsync() ? Results.Ok(new { email=u.Email, prefix=r.GetString(0), avatar=r.GetString(1) }) : Results.Ok(new { email=u.Email, prefix="", avatar="" });
});
app.MapPut("/api/profile", async (HttpRequest req, ProfileInput input) => {
 var u=await GetUser(req); if(u is null)return Results.Unauthorized();
 if((input.Prefix?.Length??0)>16)return Results.BadRequest(new{error="Префикс — максимум 16 символов."});
 if((input.Avatar?.Length??0)>3000000)return Results.BadRequest(new{error="Аватар слишком большой."});
 await using var c=new SqliteConnection(Conn()); await c.OpenAsync(); var q=c.CreateCommand(); q.CommandText="INSERT INTO profiles(user_id,prefix,avatar) VALUES($id,$p,$a) ON CONFLICT(user_id) DO UPDATE SET prefix=excluded.prefix,avatar=excluded.avatar"; q.Parameters.AddWithValue("$id",u.Id); q.Parameters.AddWithValue("$p",input.Prefix?.Trim()??""); q.Parameters.AddWithValue("$a",input.Avatar??""); await q.ExecuteNonQueryAsync(); return Results.Ok(new{message="Профиль сохранён."});
});
app.MapGet("/api/chat/messages", async (HttpRequest req) => {
 var u=await GetUser(req); if(u is null)return Results.Unauthorized();
 var rows=new List<object>(); await using var c=new SqliteConnection(Conn()); await c.OpenAsync(); var q=c.CreateCommand(); q.CommandText="SELECT m.id,u.email,u.role,COALESCE(p.prefix,''),COALESCE(p.avatar,''),m.content,m.message_type,m.created_utc FROM chat_messages m JOIN users u ON u.id=m.user_id LEFT JOIN profiles p ON p.user_id=u.id ORDER BY m.id DESC LIMIT 100";
 await using var r=await q.ExecuteReaderAsync(); while(await r.ReadAsync()) rows.Add(new { id=r.GetInt64(0), email=r.GetString(1), role=r.GetString(2), prefix=r.GetString(3), avatar=r.GetString(4), content=r.GetString(5), messageType=r.GetString(6), createdAtUtc=DateTime.Parse(r.GetString(7)) });
 rows.Reverse(); return Results.Ok(rows);
});
app.MapPost("/api/chat/messages", async (HttpRequest req, ChatInput input) => {
 var u=await GetUser(req); if(u is null)return Results.Unauthorized();
 var type=string.IsNullOrWhiteSpace(input.MessageType)?"text":input.MessageType.ToLowerInvariant();
 if(type!="text" && type!="image" && type!="audio")return Results.BadRequest(new{error="Неподдерживаемый тип сообщения."});
 var max=type=="text"?1000:8*1024*1024;
 if(string.IsNullOrWhiteSpace(input.Content)||input.Content.Length>max)return Results.BadRequest(new{error=type=="text"?"Сообщение должно содержать 1–1000 символов.":"Медиафайл слишком большой (максимум 8 МБ)."});
 if(type=="image"&&!input.Content.StartsWith("data:image/"))return Results.BadRequest(new{error="Некорректная фотография."});
 if(type=="audio"&&!input.Content.StartsWith("data:audio/"))return Results.BadRequest(new{error="Некорректное голосовое сообщение."});
 await using var c=new SqliteConnection(Conn()); await c.OpenAsync();
 var profile=c.CreateCommand(); profile.CommandText="INSERT INTO profiles(user_id,prefix,avatar) VALUES($id,$p,$a) ON CONFLICT(user_id) DO UPDATE SET prefix=excluded.prefix,avatar=excluded.avatar"; profile.Parameters.AddWithValue("$id",u.Id); profile.Parameters.AddWithValue("$p",(input.Prefix??"").Trim()); profile.Parameters.AddWithValue("$a",input.Avatar??""); await profile.ExecuteNonQueryAsync();
 var q=c.CreateCommand(); q.CommandText="INSERT INTO chat_messages(user_id,content,message_type,created_utc) VALUES($id,$c,$t,$d)"; q.Parameters.AddWithValue("$id",u.Id); q.Parameters.AddWithValue("$c",input.Content.Trim()); q.Parameters.AddWithValue("$t",type); q.Parameters.AddWithValue("$d",DateTime.UtcNow.ToString("O")); await q.ExecuteNonQueryAsync(); return Results.Ok(new{message="Сообщение отправлено."});
});
app.MapPost("/api/auth/register", async (AuthInput input) => {
 if (!ValidEmail(input.Email) || input.Password.Length < 8) return Results.BadRequest(new { error = "Укажите корректную почту и пароль минимум из 8 символов." });
 var salt = Convert.ToBase64String(RandomNumberGenerator.GetBytes(16)); var hash = Hash(input.Password, salt);
 try { long id; await using var c = new SqliteConnection(Conn()); await c.OpenAsync(); var cmd=c.CreateCommand(); cmd.CommandText="INSERT INTO users(email,password_hash,password_salt,created_utc) VALUES($e,$h,$s,$d); SELECT last_insert_rowid();"; cmd.Parameters.AddWithValue("$e",input.Email.Trim().ToLowerInvariant()); cmd.Parameters.AddWithValue("$h",hash); cmd.Parameters.AddWithValue("$s",salt); cmd.Parameters.AddWithValue("$d",DateTime.UtcNow.ToString("O")); id=(long)(await cmd.ExecuteScalarAsync())!; return Results.Ok(await NewSession(id)); }
 catch (SqliteException) { return Results.Conflict(new { error="Аккаунт с такой почтой уже существует." }); }
});
app.MapPost("/api/auth/login", async (AuthInput input) => {
 await using var c=new SqliteConnection(Conn()); await c.OpenAsync(); var cmd=c.CreateCommand(); cmd.CommandText="SELECT id,password_hash,password_salt FROM users WHERE email=$e"; cmd.Parameters.AddWithValue("$e",input.Email.Trim().ToLowerInvariant()); await using var r=await cmd.ExecuteReaderAsync(); if(!await r.ReadAsync()) return Results.Unauthorized(new { error="Неверная почта или пароль." }); var id=r.GetInt64(0); var hash=r.IsDBNull(1)?null:r.GetString(1); var salt=r.IsDBNull(2)?null:r.GetString(2); await r.CloseAsync(); if(hash is null||salt is null||!CryptographicOperations.FixedTimeEquals(Convert.FromBase64String(hash),Convert.FromBase64String(Hash(input.Password,salt)))) return Results.Unauthorized(new { error="Неверная почта или пароль." }); return Results.Ok(await NewSession(id));
});
app.MapPost("/api/auth/google", async (GoogleInput input) => {
 if(string.IsNullOrWhiteSpace(input.AccessToken)) return Results.BadRequest(new {error="Не получен токен Google."});
 using var http=new HttpClient(); using var req=new HttpRequestMessage(HttpMethod.Get,"https://www.googleapis.com/oauth2/v3/userinfo"); req.Headers.Authorization=new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer",input.AccessToken); using var resp=await http.SendAsync(req); if(!resp.IsSuccessStatusCode) return Results.Unauthorized(new {error="Google не подтвердил вход."}); using var doc=JsonDocument.Parse(await resp.Content.ReadAsStringAsync()); var email=doc.RootElement.TryGetProperty("email",out var em)?em.GetString():null; var sub=doc.RootElement.TryGetProperty("sub",out var su)?su.GetString():null; var verified=doc.RootElement.TryGetProperty("email_verified",out var ev)&&ev.GetBoolean(); if(string.IsNullOrWhiteSpace(email)||string.IsNullOrWhiteSpace(sub)||!verified) return Results.Unauthorized(new {error="Google не подтвердил адрес почты."});
 await using var c=new SqliteConnection(Conn()); await c.OpenAsync(); var find=c.CreateCommand(); find.CommandText="SELECT id FROM users WHERE google_sub=$s OR email=$e"; find.Parameters.AddWithValue("$s",sub); find.Parameters.AddWithValue("$e",email.ToLowerInvariant()); var obj=await find.ExecuteScalarAsync(); long id; if(obj is null){var ins=c.CreateCommand(); ins.CommandText="INSERT INTO users(email,google_sub,created_utc) VALUES($e,$s,$d); SELECT last_insert_rowid();"; ins.Parameters.AddWithValue("$e",email.ToLowerInvariant()); ins.Parameters.AddWithValue("$s",sub); ins.Parameters.AddWithValue("$d",DateTime.UtcNow.ToString("O")); id=(long)(await ins.ExecuteScalarAsync())!;} else {id=Convert.ToInt64(obj); var upd=c.CreateCommand(); upd.CommandText="UPDATE users SET google_sub=$s WHERE id=$id"; upd.Parameters.AddWithValue("$s",sub); upd.Parameters.AddWithValue("$id",id); await upd.ExecuteNonQueryAsync();} return Results.Ok(await NewSession(id));
});
app.MapPost("/api/auth/change-password", async (HttpRequest req, ChangePasswordInput input) => { var user=await GetUser(req); if(user is null)return Results.Unauthorized(); if(input.NewPassword.Length<8)return Results.BadRequest(new{error="Новый пароль должен содержать минимум 8 символов."}); await using var c=new SqliteConnection(Conn()); await c.OpenAsync(); var q=c.CreateCommand(); q.CommandText="SELECT password_hash,password_salt FROM users WHERE id=$id"; q.Parameters.AddWithValue("$id",user.Id); await using var r=await q.ExecuteReaderAsync(); await r.ReadAsync(); var oldHash=r.IsDBNull(0)?null:r.GetString(0); var oldSalt=r.IsDBNull(1)?null:r.GetString(1); await r.CloseAsync(); if(oldHash is null||oldSalt is null||!CryptographicOperations.FixedTimeEquals(Convert.FromBase64String(oldHash),Convert.FromBase64String(Hash(input.CurrentPassword,oldSalt))))return Results.BadRequest(new{error="Текущий пароль указан неверно. Для Google-аккаунта сначала задайте пароль через восстановление пароля."}); var salt=Convert.ToBase64String(RandomNumberGenerator.GetBytes(16)); var upd=c.CreateCommand(); upd.CommandText="UPDATE users SET password_hash=$h,password_salt=$s WHERE id=$id"; upd.Parameters.AddWithValue("$h",Hash(input.NewPassword,salt));upd.Parameters.AddWithValue("$s",salt);upd.Parameters.AddWithValue("$id",user.Id);await upd.ExecuteNonQueryAsync(); return Results.Ok(new{message="Пароль изменён."}); });
app.MapGet("/api/subscription", async (HttpRequest req) => { var u=await GetUser(req); if(u is null)return Results.Unauthorized(); await using var c=new SqliteConnection(Conn());await c.OpenAsync();var q=c.CreateCommand();q.CommandText="SELECT plan,plan_expires,role FROM users WHERE id=$id";q.Parameters.AddWithValue("$id",u.Id);await using var r=await q.ExecuteReaderAsync();await r.ReadAsync();var plan=r.GetString(0);DateTime? exp=DateTime.TryParse(r.IsDBNull(1)?null:r.GetString(1),out var dt)?dt:(DateTime?)null;var role=r.GetString(2);if(exp.HasValue&&exp.Value<DateTime.UtcNow){plan="Free";await r.CloseAsync();var up=c.CreateCommand();up.CommandText="UPDATE users SET plan='Free',plan_expires=NULL WHERE id=$id";up.Parameters.AddWithValue("$id",u.Id);await up.ExecuteNonQueryAsync();}return Results.Ok(new{plan,expiresAtUtc=exp,isAdmin=role=="admin",message=plan=="Free"?"Базовый бесплатный план активен.":"Промо-подписка активна."}); });
app.MapPost("/api/promo/redeem", async (HttpRequest req, PromoInput input) => {var u=await GetUser(req);if(u is null)return Results.Unauthorized();await using var c=new SqliteConnection(Conn());await c.OpenAsync();var q=c.CreateCommand();q.CommandText="SELECT duration_days,max_uses,uses,expires_utc FROM promos WHERE code=$code COLLATE NOCASE";q.Parameters.AddWithValue("$code",input.Code.Trim());await using var r=await q.ExecuteReaderAsync();if(!await r.ReadAsync())return Results.BadRequest(new{error="Промокод не найден."});int days=r.GetInt32(0),max=r.GetInt32(1),uses=r.GetInt32(2);var exp=DateTime.Parse(r.GetString(3));await r.CloseAsync();if(exp<DateTime.UtcNow||uses>=max)return Results.BadRequest(new{error="Промокод истёк или закончились активации."});var update=c.CreateCommand();update.CommandText="UPDATE promos SET uses=uses+1 WHERE code=$code AND uses < max_uses";update.Parameters.AddWithValue("$code",input.Code.Trim());if(await update.ExecuteNonQueryAsync()!=1)return Results.BadRequest(new{error="Промокод уже исчерпан."});var until=DateTime.UtcNow.AddDays(days);var sub=c.CreateCommand();sub.CommandText="UPDATE users SET plan='Promo',plan_expires=$e WHERE id=$id";sub.Parameters.AddWithValue("$e",until.ToString("O"));sub.Parameters.AddWithValue("$id",u.Id);await sub.ExecuteNonQueryAsync();return Results.Ok(new{plan="Promo",expiresAtUtc=until,isAdmin=u.Role=="admin",message=$"Промо-подписка активна ещё {days} дней."});});
app.MapPost("/api/admin/promos", async (HttpRequest req, PromoCreate input) => {var u=await GetUser(req);if(u?.Role!="admin")return Results.Forbid();if(input.DurationDays<1||input.DurationDays>3650||input.MaxUses<1||string.IsNullOrWhiteSpace(input.Code))return Results.BadRequest(new{error="Укажите код, срок 1–3650 дней и число активаций от 1."});var expires=DateTime.UtcNow.AddDays(3650);await using var c=new SqliteConnection(Conn());await c.OpenAsync();var q=c.CreateCommand();q.CommandText="INSERT INTO promos(code,duration_days,max_uses,uses,expires_utc,created_by) VALUES($c,$d,$m,0,$e,$u)";q.Parameters.AddWithValue("$c",input.Code.Trim());q.Parameters.AddWithValue("$d",input.DurationDays);q.Parameters.AddWithValue("$m",input.MaxUses);q.Parameters.AddWithValue("$e",expires.ToString("O"));q.Parameters.AddWithValue("$u",u.Id);try{await q.ExecuteNonQueryAsync();}catch(SqliteException){return Results.Conflict(new{error="Такой промокод уже существует."});}return Results.Ok(new{code=input.Code.Trim(),expiresAtUtc=expires});});
app.MapGet("/api/app-version", async (string? current) => {var s=await ReadSettings();string latest=s.GetValueOrDefault("latestVersion","1.2.0"),min=s.GetValueOrDefault("minimumVersion","1.2.0");return Results.Ok(new{latestVersion=latest,minimumVersion=min,downloadUrl=s.GetValueOrDefault("downloadUrl",""),message=s.GetValueOrDefault("updateMessage","Установите актуальную версию."),mustUpdate=CompareVersion(current??"0.0.0",min)<0});});
app.MapPost("/api/admin/version", async (HttpRequest req, VersionUpdate input) => {var u=await GetUser(req);if(u?.Role!="admin")return Results.Forbid();await SetSetting("latestVersion",input.LatestVersion);await SetSetting("minimumVersion",input.MinimumVersion);await SetSetting("downloadUrl",input.DownloadUrl);await SetSetting("updateMessage",input.Message);return Results.Ok(new{message="Настройки версии обновлены."});});

