 var q=c.CreateCommand(); q.CommandText="SELECT id,email,role,plan,plan_expires,created_utc FROM users ORDER BY id DESC LIMIT 500";
 await using var r=await q.ExecuteReaderAsync(); while(await r.ReadAsync()) rows.Add(new { id=r.GetInt64(0), email=r.GetString(1), role=r.GetString(2), plan=r.GetString(3), expiresAtUtc=r.IsDBNull(4)?null:r.GetString(4), createdAtUtc=r.GetString(5) });
 return Results.Ok(rows);
