app.MapGet("/api/admin/promos", async (HttpRequest req) => {
 var u=await GetUser(req); if(u?.Role!="admin") return Results.Forbid();
 var rows=new List<object>(); await using var c=new SqliteConnection(Conn()); await c.OpenAsync();
 var q=c.CreateCommand(); q.CommandText="SELECT code,duration_days,max_uses,uses,expires_utc FROM promos ORDER BY rowid DESC";
 await using var r=await q.ExecuteReaderAsync(); while(await r.ReadAsync()) rows.Add(new { code=r.GetString(0), durationDays=r.GetInt32(1), maxUses=r.GetInt32(2), uses=r.GetInt32(3), expiresAtUtc=r.GetString(4) });
 return Results.Ok(rows);
