app.MapDelete("/api/admin/promos/{code}", async (HttpRequest req, string code) => {
 var u=await GetUser(req); if(u?.Role!="admin") return Results.Forbid();
 await using var c=new SqliteConnection(Conn()); await c.OpenAsync(); var q=c.CreateCommand(); q.CommandText="DELETE FROM promos WHERE code=$code"; q.Parameters.AddWithValue("$code",code); await q.ExecuteNonQueryAsync(); return Results.Ok(new{message="Промокод удалён."});
});
app.MapPost("/api/admin/users/{id:long}/plan", async (HttpRequest req, long id, UserPlanUpdate input) => {
 var u=await GetUser(req); if(u?.Role!="admin") return Results.Forbid();
 if(input.Plan!="Free" && input.Plan!="Promo") return Results.BadRequest(new{error="Допустимы планы Free или Promo."});
 DateTime? until=null; if(input.Plan=="Promo"){ if(input.DurationDays<1||input.DurationDays>3650)return Results.BadRequest(new{error="Срок должен быть 1–3650 дней."}); until=DateTime.UtcNow.AddDays(input.DurationDays); }
 await using var c=new SqliteConnection(Conn()); await c.OpenAsync(); var q=c.CreateCommand(); q.CommandText="UPDATE users SET plan=$p,plan_expires=$e WHERE id=$id"; q.Parameters.AddWithValue("$p",input.Plan); q.Parameters.AddWithValue("$e",until?.ToString("O") is string e?e:(object)DBNull.Value); q.Parameters.AddWithValue("$id",id); if(await q.ExecuteNonQueryAsync()==0)return Results.NotFound(new{error="Пользователь не найден."}); return Results.Ok(new{message="Подписка пользователя обновлена."});
});
app.MapGet("/api/admin/settings", async (HttpRequest req) => { var u=await GetUser(req); if(u?.Role!="admin")return Results.Forbid(); return Results.Ok(await ReadSettings()); });

app.Run();

async Task EnsureAdmin(string email,string password){await using var c=new SqliteConnection(Conn());await c.OpenAsync();var q=c.CreateCommand();q.CommandText="SELECT id FROM users WHERE email=$e";q.Parameters.AddWithValue("$e",email.ToLowerInvariant());var id=await q.ExecuteScalarAsync();var salt=Convert.ToBase64String(RandomNumberGenerator.GetBytes(16));if(id is null){var ins=c.CreateCommand();ins.CommandText="INSERT INTO users(email,password_hash,password_salt,role,created_utc) VALUES($e,$h,$s,'admin',$d)";ins.Parameters.AddWithValue("$e",email.ToLowerInvariant());ins.Parameters.AddWithValue("$h",Hash(password,salt));ins.Parameters.AddWithValue("$s",salt);ins.Parameters.AddWithValue("$d",DateTime.UtcNow.ToString("O"));await ins.ExecuteNonQueryAsync();}else{var upd=c.CreateCommand();upd.CommandText="UPDATE users SET role='admin',password_hash=$h,password_salt=$s WHERE email=$e";upd.Parameters.AddWithValue("$h",Hash(password,salt));upd.Parameters.AddWithValue("$s",salt);upd.Parameters.AddWithValue("$e",email.ToLowerInvariant());await upd.ExecuteNonQueryAsync();}}
async Task<AuthReply> NewSession(long id){await using var c=new SqliteConnection(Conn());await c.OpenAsync();var q=c.CreateCommand();q.CommandText="SELECT email,role FROM users WHERE id=$id";q.Parameters.AddWithValue("$id",id);await using var r=await q.ExecuteReaderAsync();await r.ReadAsync();var email=r.GetString(0);var role=r.GetString(1);var token=Convert.ToBase64String(RandomNumberGenerator.GetBytes(48)).TrimEnd('=').Replace('+','-').Replace('/','_');await r.CloseAsync();var ins=c.CreateCommand();ins.CommandText="INSERT INTO sessions(token,user_id,expires_utc) VALUES($t,$id,$e)";ins.Parameters.AddWithValue("$t",token);ins.Parameters.AddWithValue("$id",id);ins.Parameters.AddWithValue("$e",DateTime.UtcNow.AddDays(30).ToString("O"));await ins.ExecuteNonQueryAsync();return new AuthReply(token,new UserReply(email,role));}
async Task<UserRecord?> GetUser(HttpRequest req){var token=req.Headers.Authorization.ToString().Replace("Bearer ","",StringComparison.OrdinalIgnoreCase).Trim();if(token.Length==0)return null;await using var c=new SqliteConnection(Conn());await c.OpenAsync();var q=c.CreateCommand();q.CommandText="SELECT u.id,u.email,u.role FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=$t AND s.expires_utc>$now";q.Parameters.AddWithValue("$t",token);q.Parameters.AddWithValue("$now",DateTime.UtcNow.ToString("O"));await using var r=await q.ExecuteReaderAsync();return await r.ReadAsync()?new UserRecord(r.GetInt64(0),r.GetString(1),r.GetString(2)):null;}
async Task<Dictionary<string,string>> ReadSettings(){var d=new Dictionary<string,string>();await using var c=new SqliteConnection(Conn());await c.OpenAsync();var q=c.CreateCommand();q.CommandText="SELECT key,value FROM settings";await using var r=await q.ExecuteReaderAsync();while(await r.ReadAsync())d[r.GetString(0)]=r.GetString(1);return d;}
async Task SetSetting(string key,string value){await using var c=new SqliteConnection(Conn());await c.OpenAsync();var q=c.CreateCommand();q.CommandText="INSERT INTO settings(key,value) VALUES($k,$v) ON CONFLICT(key) DO UPDATE SET value=excluded.value";q.Parameters.AddWithValue("$k",key);q.Parameters.AddWithValue("$v",value);await q.ExecuteNonQueryAsync();}
static string Hash(string password,string salt)=>Convert.ToBase64String(Rfc2898DeriveBytes.Pbkdf2(password,Convert.FromBase64String(salt),210000,HashAlgorithmName.SHA256,32));
static bool ValidEmail(string e)=>e.Length<255&&e.Contains('@')&&e.Contains('.')&&!e.Contains(' ');
static int CompareVersion(string a,string b){try{return new Version(a.Split('-')[0]).CompareTo(new Version(b.Split('-')[0]));}catch{return -1;}}
record ProfileInput(string? Prefix,string? Avatar);record ChatInput(string Content,string? Prefix,string? Avatar,string? MessageType);record UserPlanUpdate(string Plan,int DurationDays);record AuthInput(string Email,string Password);record GoogleInput(string AccessToken);record ChangePasswordInput(string CurrentPassword,string NewPassword);record PromoInput(string Code);record PromoCreate(string Code,int DurationDays,int MaxUses);record VersionUpdate(string LatestVersion,string MinimumVersion,string DownloadUrl,string Message);record AuthReply(string Token,UserReply User);record UserReply(string Email,string Role);record UserRecord(long Id,string Email,string Role);
